from core import *

@register('limits','implicit-exponential-saddle','inverse-coefficient-saddle-asymptotic','Lagrange-inversion-and-global-circle-saddle','A nonlinear analytic inverse defines the coefficients indirectly. Lagrange inversion exposes a contour integral, whose unique global saddle and local variance determine the prefactor as well as the growth rate.','The algebraic inverse ODE family has a closed binomial coefficient. The quadratic exponential here gives a nonalgebraic inverse and a two-frequency saddle; no scalar change turns it into that polynomial inverse.',[{'caseId':'critical-point-'+str(tau),'tau':str(tau),'purpose':'The relative linear and quadratic exponential weights vary dimensionlessly; not a coefficient-only rescaling.'} for tau in [R(1,2),R(1,3),R(2,3),R(1,4),R(3,4),R(2,5),R(3,5),R(1,5),R(4,5),R(2,7),R(3,7),R(4,7),R(5,7),R(3,8),R(5,8),R(7,8)]],['analytic implicit functions','Lagrange inversion','contour coefficient formula','dominated saddle asymptotics'])
def exponential_saddle(case):
 tau=R(case['tau']);c=(1-tau)/(2*tau*tau);rho=tau*s.exp(-(1+tau)/2);variance=tau+4*c*tau*tau;A=tau/s.sqrt(2*pi*variance);theta=s.symbols('theta',real=True)
 ck('Stationary point removes the entire linear phase',tau+2*c*tau*tau,1)
 phase=tau*(s.exp(s.I*theta)-1)+c*tau*tau*(s.exp(2*s.I*theta)-1)-s.I*theta
 ck('Independent second derivative gives the full two-frequency variance',s.diff(phase,theta,2).subs(theta,0),-variance)
 ck('The exponential growth scale includes both exponential terms',tau*s.exp(-tau-c*tau*tau),rho)
 # Exact low-order coefficient check through the implicit equation, independently of the saddle argument.
 M=6;coeff={N:s.simplify(sum((N*c)**j*s.Integer(N)**(N-1-2*j)/(s.factorial(j)*s.factorial(N-1-2*j)) for j in range((N-1)//2+1))/N) for N in range(1,M+1)}
 Y=sum(v*x**N for N,v in coeff.items());res=s.series(Y-x*s.exp(Y+c*Y*Y),x,0,M+1).removeO();ck('Independent substitution verifies the actual coefficient formula through order six',res,0)
 condition('The saddle is unique on the full integration circle',0<tau<1 and c>0,'The real phase is tau(cos theta-1)+c tau squared(cos2theta-1), strictly negative for every nonzero theta in[-pi,pi].')
 analytic('Full-circle saddle with exact prefactor',['The positive quadratic exponential coefficient and critical point are the displayed finite rational values. The analytic implicit solution exists uniquely near zero by the implicit-function theorem.'],['Lagrange inversion gives a_n=(1/n)[u^(n-1)]exp(n(u+cu squared)). Integrate on the circle u=tau exp(i theta).','After extracting rho^(-n), the remaining prefactor is tau/n and the integral is exp(n Phi(theta))exp(i theta), divided by2pi. Stationarity is tau+2c tau squared=1.','The real phase equals tau(cos theta-1)+c tau squared(cos2theta-1). Its unique maximum on[-pi,pi] is zero at theta0; outside every fixed neighborhood it is bounded above by a negative constant.','Near zero Phi(theta)=-variance*theta squared/2+O(theta cubed), with variance=tau+4c tau squared>0. Rescale theta=v/sqrt(n), dominate by a fixed Gaussian in a small neighborhood, and discard the exponentially small complement.','The local integral is asymptotic to sqrt(2pi/(n*variance)). Multiplying the coefficient prefactor gives tau/sqrt(2pi*variance), with the power n^(-3/2).'])
 pool=[(1/s.sqrt(2*pi*variance),'Lose the extra radius factor from coefficient n minus one'),(tau/s.sqrt(2*pi*tau),'Discard the quadratic exponential contribution to the saddle variance'),(tau/s.sqrt(2*pi*(tau+2*c*tau*tau)),'Use the first derivative balance in place of the second derivative variance'),(tau/s.sqrt(pi*variance),'Lose the factor two in the Gaussian integral'),(tau/s.sqrt(4*pi*variance),'Count the Gaussian half-line instead of the full saddle'),(tau* s.sqrt(variance/(2*pi)),'Multiply by the curvature instead of dividing by it')]
 return candidate(T('Let Y be the unique analytic solution near zero with ')+r'Y(0)=0,\quad Y(z)=z\exp\!\left(Y(z)+'+('' if c==1 else L(c))+r'Y(z)^2\right),\quad Y(z)=\sum_{n=1}^\infty a_nz^n.'+T('Set ')+r'\rho='+L(rho)+r'.'+T('Evaluate ')+r'\lim_{n\to\infty}n^{3/2}\rho^n a_n.',A,pool,[r'a_n=\frac1n[u^{n-1}]\exp\!\left(n(u+'+('' if c==1 else L(c))+r'u^2)\right)',r'\tau='+L(tau)+r',\quad c='+L(c)+r',\quad\tau+2c\tau^2=1,\quad\rho=\tau e^{-\tau-c\tau^2}',r'a_n=\frac{\tau\rho^{-n}}{2\pi n}\int_{-\pi}^{\pi}e^{n\Phi(\theta)}e^{i\theta}\,\mathrm d\theta,\quad\Phi(\theta)=\tau(e^{i\theta}-1)+c\tau^2(e^{2i\theta}-1)-i\theta',r'\operatorname{Re}\Phi(\theta)=\tau(\cos\theta-1)+c\tau^2(\cos2\theta-1)<0\quad(0<|\theta|\le\pi)',r'\Phi(\theta)=-\frac{\sigma^2\theta^2}{2}+O(\theta^3),\qquad\sigma^2=\tau+4c\tau^2='+L(variance),T('Outside a fixed neighborhood the integral is exponentially small. Inside, rescaling by square-root n and a Gaussian bound justify dominated convergence on the expanding interval.'),r'\int_{-\pi}^{\pi}e^{n\Phi(\theta)}e^{i\theta}\,\mathrm d\theta\sim\sqrt{\frac{2\pi}{n\sigma^2}},\qquad a_n\sim\frac{\tau\rho^{-n}}{\sqrt{2\pi\sigma^2}\,n^{3/2}}'],'nonalgebraic-exponential-inverse-coefficient-global-saddle')

@register('limits','permutation-cycle-divisibility','restricted-cycle-exponential-formula','labelled-cycle-decomposition-and-Gamma-ratio','A probability over all permutations is converted into an exponential generating function by accounting for cyclic order and indistinguishable cycles. Its fractional singularity then determines the exact power-law constant.','The coupon collector counts missing labels; this problem constrains the complete cycle decomposition of a permutation and requires the cycle-index factor.',[{'caseId':'cycle-modulus-'+str(d),'d':d,'purpose':'Different permitted cycle-length lattices; modulus is a structural combinatorial invariant.'} for d in range(3,19)],['permutation cycle enumeration','exponential generating functions','generalized binomial theorem','Stirling asymptotics'])
def permutation_cycles(case):
 d=case['d'];q=R(1,d);A=1/s.gamma(q);probs=[s.Integer(1)]
 for N in range(1,5*d+1):
  probs.append(sum(probs[N-j] for j in range(d,N+1,d))/N)
  if N%d==0:ck('Independent distinguished-element cycle recurrence at size '+str(N),probs[N],s.rf(q,N//d)/s.factorial(N//d))
 u=s.symbols('u');ck('Generating function logarithmic derivative gives the cycle-lattice kernel',s.diff((1-u**d)**(-q),u)/(1-u**d)**(-q),u**(d-1)/(1-u**d))
 analytic('Permutation cycle probability asymptotic',['The permutation is uniform on the full symmetric group of size d*n; all cycles, including singleton cycles, are subject to the divisibility condition.','The Gamma function is defined for positive arguments.'],['A labelled cycle of length k has(k-1)! arrangements, so its exponential generating contribution is z^k/k. Unordered collections of allowed cycles exponentiate their sum.','The probability generating series is exp(sum z^(dj)/(dj))=(1-z^d)^(-1/d). Therefore the desired probability is(1/d)_n/n!, with no extra factorial from the ambient size.','Write this coefficient as Gamma(n+1/d)/(Gamma(1/d)Gamma(n+1)). Stirling applied at the two shifted arguments gives the ratio n^(1/d-1)(1+o1).','The requested normalization uses n, not the total number d*n of labels.'])
 pool=[(1/s.gamma(2*q),'Count both orientations of each cycle as distinct'),(1/s.gamma(q/2),'Divide the cycle weight by an extra orientation factor'),(1/s.gamma(q*q),'Apply the cycle-length factor twice'),(1/s.gamma(1-q),'Use the complementary cycle-length class'),(1/s.gamma((1+q)/2),'Average the allowed-cycle exponent with the unrestricted exponent')]
 return candidate(T('Choose a permutation uniformly from all permutations of ')+r'\{1,2,\ldots,'+str(d)+r'n\}.'+T('Let ')+r'p_n'+T(' be the probability that every cycle has length divisible by ')+str(d)+T('. With ')+r'\Gamma(a)=\int_0^\infty t^{a-1}e^{-t}\,\mathrm dt\quad(a>0),'+T('evaluate ')+r'\lim_{n\to\infty}n^{'+L(1-q)+r'}p_n.',A,pool,[T('A cycle of length k on labelled elements contributes one over k to the exponential generating function. Taking an unordered collection of allowed cycles exponentiates their contributions.'),T('Let ')+r'q_N'+T(' be the analogous probability on N labels, so ')+r'p_n=q_{'+str(d)+r'n}.'+r'\qquad\sum_{N\ge0}q_Nz^N=\exp\left(\sum_{j\ge1}\frac{z^{'+str(d)+r'j}}{'+str(d)+r'j}\right)=(1-z^{'+str(d)+r'})^{-'+L(q)+r'}',r'p_n=[z^{'+str(d)+r'n}](1-z^{'+str(d)+r'})^{-'+L(q)+r'}=\frac{\Gamma(n+'+L(q)+r')}{\Gamma('+L(q)+r')\Gamma(n+1)}',T('The ambient factorial has already canceled because these are probabilities, not counts. Stirling at two fixed shifts gives the ratio below.'),r'\frac{\Gamma(n+'+L(q)+r')}{\Gamma(n+1)}\sim n^{'+L(q-1)+r'}'],'restricted-permutation-cycle-lattice-Gamma-limit')

@register('limits','random-walk-last-zero-law','last-zero-arcsine-distribution','last-exit-decomposition-and-singular-Riemann-sum','The final zero time has a nonuniform law concentrated near both ends. A last-exit decomposition gives an exact convolution, and its limiting Riemann sum requires explicit control of both singular endpoints.','An ordinary central limit tail concerns one observation time. Here the statistic depends on the entire path and a future nonreturn event after the last zero.',[{'caseId':'observation-fraction-'+str(a),'a':str(a),'purpose':'Distinct dimensionless observation fractions, avoiding symmetry-only halves.'} for a in [R(1,4),R(1,9),R(4,9),R(1,16),R(9,16),R(1,5),R(2,5),R(3,5),R(4,5),R(1,7),R(2,7),R(3,7),R(4,7),R(5,7),R(6,7),R(3,4)]],['simple symmetric random walk','reflection/ballot counting','central binomial estimates','integrable endpoint singularities'])
def last_zero(case):
 a=R(case['a']);A=2*s.asin(s.sqrt(a))/pi
 # Finite path enumeration independently checks the complete last-zero convolution.
 for N in [2,3,4]:
  counts=[0]*(N+1)
  for steps in itertools.product([-1,1],repeat=2*N):
   pos=0;last=0
   for j,step in enumerate(steps,1):
    pos+=step
    if pos==0:last=j
   counts[last//2]+=1
  for j in range(N+1):ck('Independent path count at length '+str(2*N)+' and last zero '+str(2*j),R(counts[j],2**(2*N)),s.binomial(2*j,j)*s.binomial(2*(N-j),N-j)/4**N)
 theta=s.symbols('theta',positive=True);ck('CDF derivative matches the arcsine density',s.diff(2*s.asin(s.sqrt(x))/pi,x),1/(pi*s.sqrt(x)*s.sqrt(1-x)))
 analytic('Last-zero distribution and endpoint control',['The increments are independent and take the values plus/minus one with equal probability. The last zero includes time zero.','The observation fraction is strictly between zero and one.'],['Let u_j=binomial(2j,j)/4^j. A reflection/ballot count gives probability u_m of no return to zero during the next2m steps after time zero. Independence at a specified last zero gives P(L_(2n)=2k)=u_k*u_(n-k).','Stirling gives u_k~1/sqrt(pi*k), and the central-binomial estimate u_k<=C/sqrt(k+1) holds uniformly, including k0.','On any fixed closed subinterval of(0,1), the last-zero probabilities give an ordinary Riemann sum for1/(pi sqrt(t(1-t))).','The sum of terms with k<=delta*n is at most C sqrt(delta)+O(n^(-1/2)); the same bound holds near the other endpoint. These estimates justify removing the truncation.','Integrate the density from zero to the stated fraction using t=sin squared(theta), obtaining2arcsin(sqrt(a))/pi.'])
 pool=[(s.asin(s.sqrt(a))/pi,'Forget the two signs of the no-return excursion'),(s.sqrt(a),'Retain only the lower-endpoint square-root singularity'),(1-A,'Use the complementary observation event'),(a,'Assume the last zero is uniform in time'),(2*s.asin(a)/pi,'Omit the square root in the sine-squared substitution'),(1-s.sqrt(1-a),'Retain only the upper-endpoint square-root singularity')]
 return candidate(T('Let ')+r'S_0=0'+T(' and let the increments be independent, each equal to plus one or minus one with probability one half. Define ')+r'L_{2n}=\max\{0\le j\le2n:S_j=0\}.'+T('Determine ')+r'\lim_{n\to\infty}\Pr\!\left(L_{2n}\le'+L(2*a)+r'n\right).',A,pool,[r'u_j=\frac1{4^j}\binom{2j}{j},\qquad\Pr(L_{2n}=2k)=u_ku_{n-k}',T('The first factor is return to zero at the specified time. A reflection count gives the second factor as the probability of no later return, and independence supplies their product.'),r'u_j\sim\frac1{\sqrt{\pi j}},\qquad u_j\le\frac C{\sqrt{j+1}}',T('Away from the two endpoints, the sum converges to the corresponding Riemann integral. The displayed uniform bound makes each truncated endpoint contribution at most a constant times the square root of the truncation width.'),r'\Pr(L_{2n}\le'+L(2*a)+r'n)\longrightarrow\frac1\pi\int_0^{'+L(a)+r'}\frac{\mathrm dt}{\sqrt{t(1-t)}}',r't=\sin^2\theta\quad\Longrightarrow\quad\frac1\pi\int_0^{'+L(a)+r'}\frac{\mathrm dt}{\sqrt{t(1-t)}}=\frac2\pi\arcsin\sqrt{'+L(a)+r'}'],'random-walk-path-last-zero-arcsine-CDF-limit')
